import type { CommandContext, CommandInvokeOptions } from '$PUBLIC';
const options: CommandInvokeOptions = { signal: undefined };
declare const context: CommandContext;
context.invoke?.('true', [], options);
context.invoke?.('true', [], { signal: undefined });

import type { CommandInvokeOptions } from '$PUBLIC';
import type { ShellInvokeOptions, ShellCommandContext } from '$SHELL';
const internal: ShellInvokeOptions = { signal: undefined };
const publicOptions: CommandInvokeOptions = internal;
const back: ShellInvokeOptions = publicOptions;
declare const context: ShellCommandContext;
context.invoke('true', [], back);
context.invoke('true', [], { signal: undefined });
// @ts-expect-error signal remains readonly even when explicitly undefined
back.signal = undefined;
